//! Fixed programs for the bootstrap channel. Paths are checked positional arguments, never shell source.

pub const PROBE: &str = r#"set -eu; field() { printf "%s=" "$1"; printf "%s" "$2" | od -An -v -tx1 | tr -d " \n" | sed "s/../%&/g"; printf "\n"; }; field uname "$(uname -s) $(uname -m)"; field home "$HOME"; data="${XDG_DATA_HOME:-$HOME/.local/share}/eitri-server"; field data_dir "$data"; field state_dir "${XDG_STATE_HOME:-$HOME/.local/state}/eitri-server"; space="$data"; while ! test -d "$space"; do space=$(dirname "$space"); done; blocks=$(stat -f -c %a "$space"); size=$(stat -f -c %S "$space"); field free_bytes "$((blocks * size))"; field login_shell "${SHELL:-/bin/sh}"; field login_path "$PATH"; if command -v claude >/dev/null 2>&1; then field claude "$(command -v claude)"; fi; if command -v git >/dev/null 2>&1; then field git "$(command -v git)"; fi; glibc=$(getconf GNU_LIBC_VERSION 2>/dev/null || true); case "$glibc" in "glibc "*) field glibc "${glibc#glibc }";; esac; if command -v gzip >/dev/null 2>&1; then field gzip true; else field gzip false; fi; linger=$(loginctl show-user "$(id -u)" -p Linger --value 2>/dev/null || true); case "$linger" in yes) field linger true;; no) field linger false;; esac; kill=$(systemd-analyze cat-config systemd/logind.conf 2>/dev/null | sed -n "s/^[[:space:]]*KillUserProcesses[[:space:]]*=[[:space:]]*//p" | tail -n 1 || true); case "$kill" in yes) field kill_user_processes true;; no) field kill_user_processes false;; esac; field root missing"#;

pub const UPLOAD: &str = r#"set -eu; umask 077; d="$1/$2"; mkdir -p "$d"; exec 8<"$d"; flock -s 8; mkdir -p "$d/bin"; t=$(mktemp "$d/bin/.eitri-server.XXXXXX"); trap "rm -f -- \"\$t\"" EXIT HUP INT TERM; gzip -dc > "$t"; chmod 700 "$t"; sync "$t"; mv -f "$t" "$d/bin/eitri-server""#;

pub const UPLOAD_PLAIN: &str = r#"set -eu; umask 077; d="$1/$2"; mkdir -p "$d"; exec 8<"$d"; flock -s 8; mkdir -p "$d/bin"; t=$(mktemp "$d/bin/.eitri-server.XXXXXX"); trap "rm -f -- \"\$t\"" EXIT HUP INT TERM; cat > "$t"; chmod 700 "$t"; sync "$t"; mv -f "$t" "$d/bin/eitri-server""#;

pub const UPLOAD_SIDECAR: &str = r#"set -eu; umask 077; IFS= read -r rev; case "$rev" in ""|.|..|*[!a-f0-9-]*) exit 64;; esac; d="$1/$2"; mkdir -p "$d"; exec 8<"$d"; flock -s 8; d="$d/sidecar/$rev"; mkdir -p "$d"; t=$(mktemp "$d/.sidecar.XXXXXX"); trap "rm -f -- \"\$t\"" EXIT HUP INT TERM; gzip -dc > "$t"; chmod 700 "$t"; sync "$t"; mv -f "$t" "$d/verdandi-claude-sidecar""#;

pub const UPLOAD_SIDECAR_PLAIN: &str = r#"set -eu; umask 077; IFS= read -r rev; case "$rev" in ""|.|..|*[!a-f0-9-]*) exit 64;; esac; d="$1/$2"; mkdir -p "$d"; exec 8<"$d"; flock -s 8; d="$d/sidecar/$rev"; mkdir -p "$d"; t=$(mktemp "$d/.sidecar.XXXXXX"); trap "rm -f -- \"\$t\"" EXIT HUP INT TERM; cat > "$t"; chmod 700 "$t"; sync "$t"; mv -f "$t" "$d/verdandi-claude-sidecar""#;

pub const WRITE_MANIFEST: &str = r#"set -eu; umask 077; d="$1/$2"; exec 8<"$d"; flock -s 8; t=$(mktemp "$d/.manifest.XXXXXX"); trap "rm -f -- \"\$t\"" EXIT HUP INT TERM; cat > "$t"; sync "$t"; mv -f "$t" "$d/MANIFEST""#;

pub const PUBLISH: &str = r#"set -eu; umask 077; IFS= read -r version; IFS= read -r rev; case "$version" in ""|.|..|*[!A-Za-z0-9._+-]*) exit 64;; esac; case "$rev" in ""|.|..|*[!a-f0-9-]*) exit 64;; esac; s="$1/$2"; exec 8<"$s"; flock -s 8; d="$1/$version"; exec 9>"$1/.install.lock"; flock -x 9; find "$1" -mindepth 1 -maxdepth 1 -type d -name ".install-*" ! -path "$s" -mmin +1439 -exec flock -n -x {} rm -rf -- {} \;; cd "$s"; sha256sum --strict --quiet -c MANIFEST; if test -e "$d/MANIFEST"; then cmp -s "$s/MANIFEST" "$d/MANIFEST" || { echo "installation identity already contains different hashes" >&2; exit 65; }; fi; mkdir -p "$d/bin" "$d/sidecar/$rev"; mv -f "$s/bin/eitri-server" "$d/bin/eitri-server"; mv -f "$s/sidecar/$rev/verdandi-claude-sidecar" "$d/sidecar/$rev/verdandi-claude-sidecar"; mv -f "$s/MANIFEST" "$d/MANIFEST"; sync "$d"; rm -rf -- "$s""#;

pub const CLEANUP: &str = r#"set -eu; case "$2" in .install-*) rm -rf -- "$1/$2";; *) exit 64;; esac"#;

pub const START: &str = r#"set -eu; d="$1/$2"; exec 9>"$1/.install.lock"; flock -s 9; cd "$d"; sha256sum --strict --quiet -c -; (exec ./bin/eitri-server ensure) 9>&-"#;

pub const STOP: &str = r#"set -eu; exec 9>"$1/.install.lock"; flock -s 9; cd "$1/$2"; sha256sum --strict --quiet -c -; (exec ./bin/eitri-server stop-daemon --args-hex "$3") 9>&-"#;
